#include <iostream>
using namespace std;

int main() {
    long long a, b, m, r0;
    cin >> a >> b >> m >> r0;

    auto next = [&](long long r) {
        return (a * r + b) % m;
    };

    long long slow = next(r0);
    long long fast = next(next(r0));

    while (slow != fast) {
        slow = next(slow);
        fast = next(next(fast));
    }

    long long cycleLength = 1;
    fast = next(slow);
    while (slow != fast) {
        fast = next(fast);
        ++cycleLength;
    }

    cout << cycleLength;
    return 0;
}

